import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.YiAtXB4p.js";const m=JSON.parse('{"title":"Examples","description":"","frontmatter":{"title":"Examples"},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md"}'),n={name:"examples/index.md"};function d(o,t,i,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>58 runnable programs from <a href="https://github.com/lgriffin/ESI.ts/tree/master/examples" target="_blank" rel="noreferrer"><code>examples/</code></a>, each shown here as it is in the repository. CI type-checks every one of them with <code>npm run typecheck:examples</code>, and the ones that need no token run against live ESI every night; a failure opens an issue. Every page says what the program needs and the command that runs it.</p><h2 id="client-features" tabindex="-1">Client features <a class="header-anchor" href="#client-features" aria-label="Permalink to &quot;Client features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th><th>Needs</th></tr></thead><tbody><tr><td><a href="./cursor-pagination">Cursor-based Pagination Example</a></td><td>ESI uses cursor-based pagination for newer routes like Freelance Jobs.</td><td>Token optional</td></tr><tr><td><a href="./public-vs-authenticated">Public versus authenticated, at the type level</a></td><td><code>esi.public</code> is a <code>PublicScopeTree</code>: the operations that need no SSO scope.</td><td>No token needed</td></tr><tr><td><a href="./rate-limiting">Rate Limiting &amp; Pagination</a></td><td>Demonstrates rate-limiting awareness, pagination with large datasets, and error handling for non-existent resources.</td><td>No token needed</td></tr><tr><td><a href="./retry-timeout-metadata">Retry, Timeout &amp; Response Metadata</a></td><td>Demonstrates retry with exponential backoff, request timeouts, TimeoutError handling, and rich response metadata via withMetadata().</td><td>No token needed</td></tr><tr><td><a href="./streaming-pagination">Streaming Pagination</a></td><td>Demonstrates streaming through large paginated datasets page-by-page instead of loading everything into memory at once.</td><td>No token needed</td></tr><tr><td><a href="./universe-post-helpers">Universe POST Helpers &amp; Character Affiliation</a></td><td>Demonstrates the three safe read-only POST endpoints.</td><td>No token needed</td></tr><tr><td><a href="./write-operations">Write Operations (Contacts, Fittings, Mail)</a></td><td>Demonstrates create → verify → cleanup for reversible write endpoints.</td><td>Needs an access token</td></tr></tbody></table><h2 id="tokens-and-characters" tabindex="-1">Tokens and characters <a class="header-anchor" href="#tokens-and-characters" aria-label="Permalink to &quot;Tokens and characters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th><th>Needs</th></tr></thead><tbody><tr><td><a href="./multi-character">Many characters, one runtime</a></td><td>Reads the wallet balance of every character an EsiTokenManager holds, through one shared runtime: one rate limiter, one error budget and one ETag cache for the whole application, and an immutable view per character.</td><td>Needs an access token</td></tr><tr><td><a href="./token-manager">Token Manager</a></td><td>Demonstrates EsiTokenManager: the SSO login flow, persistent multi-character token storage, proactive refresh, a view for a character over the shared runtime (<code>esi.as(tokens.identity(id))</code>), and bulk refresh with a concurrency cap.</td><td>Needs an access token</td></tr><tr><td><a href="./token-refresh">Token Refresh</a></td><td>Demonstrates automatic token refresh using the onTokenRefresh callback.</td><td>Needs an access token</td></tr></tbody></table><h2 id="public-data" tabindex="-1">Public data <a class="header-anchor" href="#public-data" aria-label="Permalink to &quot;Public data&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th><th>Needs</th></tr></thead><tbody><tr><td><a href="./alliance-info">Alliance Information</a></td><td>Looks up an alliance, its member corporations, and icons.</td><td>No token needed</td></tr><tr><td><a href="./character-lookup">Character Lookup</a></td><td>Looks up a character&#39;s public info, portrait, and corporation.</td><td>No token needed</td></tr><tr><td><a href="./corporation-history">Corporation History and NPC Corporations</a></td><td>Follows a character&#39;s employment history, the alliance history and logo of their current corporation, then lists the NPC corporations and the loyalty store offers of one of them.</td><td>No token needed</td></tr><tr><td><a href="./dogma">Dogma &amp; Item Types</a></td><td>Explores EVE&#39;s game mechanics data: item types, dogma attributes, and effects.</td><td>No token needed</td></tr><tr><td><a href="./dogma-meta-sov">Dogma Effects, Meta API &amp; Sovereignty Systems</a></td><td>Demonstrates dogma effects lookup, the ESI OpenAPI spec endpoint, sovereignty system ownership, and war killmails.</td><td>No token needed</td></tr><tr><td><a href="./meta">ESI Metadata</a></td><td>Reads ESI&#39;s own metadata: the API name, the compatibility dates it accepts, the latest changelog entries, and the health of each route.</td><td>No token needed</td></tr><tr><td><a href="./character-profile">ESI.ts - Working Example: Complete Character Profile</a></td><td>This demonstrates how to use the ESI.ts library to gather comprehensive character information by combining multiple API calls efficiently.</td><td>Token optional</td></tr><tr><td><a href="./faction-warfare-details">Faction Warfare Details</a></td><td>Demonstrates faction warfare leaderboards (overall, characters, corporations), faction wars, and per-character/corporation FW stats.</td><td>Token optional</td></tr><tr><td><a href="./incursions">Incursions &amp; Faction Warfare</a></td><td>Shows active Sansha incursions and faction warfare statistics.</td><td>No token needed</td></tr><tr><td><a href="./industry">Industry &amp; Insurance</a></td><td>Fetches public industry data: facility locations, system cost indices, and insurance prices for ships.</td><td>No token needed</td></tr><tr><td><a href="./market-prices">Market Prices</a></td><td>Fetches average market prices and price history for a specific item.</td><td>No token needed</td></tr><tr><td><a href="./military-campaigns">Military Campaigns</a></td><td>Demonstrates the six military campaign endpoints.</td><td>Token optional</td></tr><tr><td><a href="./paragon-hub">Paragon Hub SKINR Marketplace</a></td><td>Browses the Paragon Hub marketplace for SKINR ship customization designs.</td><td>Token optional</td></tr><tr><td><a href="./public-contracts">Public Contracts</a></td><td>Lists the public contracts in a region, then reads the items of the first item exchange and the bids on the first auction.</td><td>No token needed</td></tr><tr><td><a href="./route-planner">Route Planner</a></td><td>Calculates the shortest route between two solar systems and looks up the name of each system along the way.</td><td>No token needed</td></tr><tr><td><a href="./status">Server Status</a></td><td>Quick check that the ESI API is reachable and the EVE server is online.</td><td>No token needed</td></tr><tr><td><a href="./cosmetics">SKINR Cosmetics</a></td><td>Looks up SKINR designs and a character&#39;s owned licenses and components.</td><td>Token optional</td></tr><tr><td><a href="./sovereignty">Sovereignty</a></td><td>Shows active sovereignty campaigns — contested structures, attack/defense scores, and event types.</td><td>No token needed</td></tr><tr><td><a href="./universe-encyclopedia">Universe Encyclopedia</a></td><td>Demonstrates the full breadth of public universe data endpoints.</td><td>No token needed</td></tr><tr><td><a href="./universe-info">Universe Information</a></td><td>Fetches solar system, station, and constellation details.</td><td>No token needed</td></tr><tr><td><a href="./wars">Wars</a></td><td>Fetches recent wars and shows details for the most recent one.</td><td>No token needed</td></tr></tbody></table><h2 id="character-and-corporation-data" tabindex="-1">Character and corporation data <a class="header-anchor" href="#character-and-corporation-data" aria-label="Permalink to &quot;Character and corporation data&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th><th>Needs</th></tr></thead><tbody><tr><td><a href="./access-lists">Access Lists</a></td><td>Retrieves an access list (ACL) and displays its entries grouped by entity type.</td><td>Needs an access token</td></tr><tr><td><a href="./assets-inventory">Asset Inventory</a></td><td>Demonstrates character asset management: listing items, looking up locations and names in bulk via POST, and summarizing inventory.</td><td>Needs an access token</td></tr><tr><td><a href="./calendar-search">Calendar &amp; Search</a></td><td>Demonstrates calendar event listing, event detail, event attendees, and character search.</td><td>Needs an access token</td></tr><tr><td><a href="./character-details">Character Details</a></td><td>Demonstrates character-specific endpoints: agents research, blueprints, roles, standings, titles, contact notifications, corporation history, jump fatigue, medals, and notifications.</td><td>Needs an access token</td></tr><tr><td><a href="./contacts">Contact Management</a></td><td>Demonstrates reading character contacts with standings and labels, and shows the available write operations (add, edit, delete contacts).</td><td>Needs an access token</td></tr><tr><td><a href="./contracts-browser">Contracts Browser</a></td><td>Demonstrates browsing public region contracts (no auth) and fetching a character&#39;s personal contracts (auth required).</td><td>Needs an access token</td></tr><tr><td><a href="./corp-contracts-wallet">Contracts, Contacts, Assets &amp; Wallet</a></td><td>Demonstrates character contract bids/items, corporation contracts, alliance/corporation contacts, corporation assets, corporation wallets (journal + transactions), and public structure lookup.</td><td>Needs an access token</td></tr><tr><td><a href="./corporation-details">Corporation Details</a></td><td>Demonstrates all corporation-level endpoints: alliance history, icon, NPC corporations, and authenticated endpoints (blueprints, divisions, facilities, medals, members, roles, shareholders, standings, structures, etc).</td><td>Needs an access token</td></tr><tr><td><a href="./corporation-projects">Corporation Projects</a></td><td>Demonstrates the Corporation Projects endpoints.</td><td>Needs an access token</td></tr><tr><td><a href="./fittings-clones">Fittings &amp; Clones</a></td><td>Demonstrates ship fitting management and clone state inspection.</td><td>Needs an access token</td></tr><tr><td><a href="./fleet-operations">Fleet Operations</a></td><td>Demonstrates fleet management: checking a character&#39;s current fleet, fetching fleet details, listing members, and inspecting wing/squad structure.</td><td>Needs an access token</td></tr><tr><td><a href="./freelance-jobs">Freelance Jobs</a></td><td>Demonstrates the four Equinox freelance job endpoints.</td><td>Needs an access token</td></tr><tr><td><a href="./industry-mining">Industry Jobs &amp; Mining</a></td><td>Demonstrates character industry jobs, mining ledger, corporation industry jobs, moon extraction timers, mining observers, and corporation killmails.</td><td>Needs an access token</td></tr><tr><td><a href="./killmails">Killmails</a></td><td>Demonstrates the two-step killmail lookup: first fetch recent killmail summaries for a character (auth required), then look up full details for each killmail using the public endpoint (no auth for the detail call).</td><td>Needs an access token</td></tr><tr><td><a href="./location-tracker">Location Tracker</a></td><td>Demonstrates real-time character location tracking: current system, online status, and current ship.</td><td>Needs an access token</td></tr><tr><td><a href="./loyalty-pi">Loyalty Points &amp; Planetary Interaction</a></td><td>Demonstrates loyalty point balances, LP store offers, planetary colonies, colony layouts, customs offices, and PI schematics.</td><td>Needs an access token</td></tr><tr><td><a href="./mail-inbox">Mail Inbox</a></td><td>Demonstrates character mail operations: reading inbox headers, viewing mail labels, listing mailing lists, and reading individual messages.</td><td>Needs an access token</td></tr><tr><td><a href="./market-orders">Market Orders &amp; Groups</a></td><td>Demonstrates character market orders, order history, corporation orders, market groups, and structure market orders.</td><td>Needs an access token</td></tr><tr><td><a href="./mercenary">Mercenary Dens &amp; Tactical Operations</a></td><td>Fetches mercenary dens across New Eden and their spawned tactical operations (MTOs), showing development and anarchy levels.</td><td>Needs an access token</td></tr><tr><td><a href="./remaining-coverage">Remaining Endpoint Coverage</a></td><td>Tests the 16 endpoints not covered by other examples.</td><td>Needs an access token</td></tr><tr><td><a href="./skills-overview">Skills Overview</a></td><td>Demonstrates character skill inspection including trained skills, skill queue, and neural remap attributes.</td><td>Needs an access token</td></tr><tr><td><a href="./skyhooks">Skyhooks &amp; Sovereignty Hubs</a></td><td>Queries Upwell sovereignty structures — sovereignty hubs, orbital skyhooks with silo levels, and currently raidable skyhooks.</td><td>Needs an access token</td></tr><tr><td><a href="./wallet-overview">Wallet Overview</a></td><td>Demonstrates character and corporation wallet operations including ISK balance, journal entries, and market transactions.</td><td>Needs an access token</td></tr></tbody></table><h2 id="static-data-export-sde" tabindex="-1">Static Data Export (SDE) <a class="header-anchor" href="#static-data-export-sde" aria-label="Permalink to &quot;Static Data Export (SDE)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th><th>Needs</th></tr></thead><tbody><tr><td><a href="./sde-industry">Blueprint &amp; Industry Data</a></td><td>Looks up a blueprint and displays its manufacturing requirements, resolving material type IDs to names via the SDE.</td><td>Needs local SDE data</td></tr><tr><td><a href="./sde-basic-lookup">SDE Basic Lookup</a></td><td>Demonstrates looking up static game data using the SDE module.</td><td>Needs local SDE data</td></tr><tr><td><a href="./sde-market-tree">SDE Market Group Tree</a></td><td>Walks the market group hierarchy recursively to display the full market category tree, optionally listing types in each leaf group.</td><td>Needs local SDE data</td></tr><tr><td><a href="./sde-fitting">Ship Fitting with Dogma Attributes</a></td><td>Looks up a ship type and its dogma attributes to display fitting-relevant stats like powergrid, CPU, slot layout, and capacitor.</td><td>Needs local SDE data</td></tr></tbody></table>',12)])])}const u=e(n,[["render",d]]);export{m as __pageData,u as default};
